  'schedule.adAddOnTicketHint': { 'zh-Hans': '已开单：该项目会立即加入当前账单。', en: 'Ticket open: this service will be added to the current bill immediately.', ko: '주문이 열려 있어 이 서비스가 현재 주문에 바로 추가됩니다.', es: 'Ticket abierto: este servicio se añadirá inmediatamente a la cuenta actual.', vi: 'Đã mở đơn: dịch vụ này sẽ được thêm ngay vào hóa đơn hiện tại.' },
  'schedule.adAddOnStaffError': { 'zh-Hans': '当前账单加项需要一位真实技师，系统已避免提交“未指定技师”。', en: 'A bill add-on needs a real therapist. The unassigned placeholder was not submitted.', ko: '현재 주문에 추가하려면 실제 담당자가 필요합니다. 미지정 값을 전송하지 않았습니다.', es: 'Un extra de ticket necesita un terapeuta real. No se envió el valor sin asignar.', vi: 'Dịch vụ thêm vào hóa đơn cần một KTV thực. Hệ thống không gửi giá trị chưa chỉ định.' },
  'schedule.adServiceItemAdded': { 'zh-Hans': '服务项目已添加到预约。', en: 'The service was added to the appointment.', ko: '서비스가 예약에 추가되었습니다.', es: 'El servicio se añadió a la cita.', vi: 'Đã thêm dịch vụ vào lịch hẹn.' },
